/*	This file gives version information of the ProDOS16 Image file.*/#define development 0x20#define alpha 0x40#define beta 0x60#define final 0x80#define langEnglish 0type 'vers' {	byte;		/* major version (2 digits) */	byte;		/* minor version (2 digits) */	byte;		/* stage of release (dev/alpha/beta/final) */	byte;		/* release number (2 digits) */	integer;	/* localization code */	pstring;	/* short version string */	pstring;	/* long version string */};/*#define shortvers $$Shell("A2GSISVersionString")#define longvers "v" $$Shell("A2GSISVersionString") ", AppleShare v2.0 Copyright © 1987-88, Apple Computer, Inc."resource 'vers' (-2, purgeable) {	0x02,	0x00,	alpha,	0x12,	langEnglish,	shortvers,	longvers};*/resource 'vers' (1, purgeable) {	0x02,	0x10,	alpha,	0x01,	langEnglish,	"2.1d7",	"Basic.System 1.3"	"\n© Apple Computer, Inc. 1988"};resource 'vers' (2,purgeable) {	0x02,	0x01,	development,	0x09,	langEnglish,	"2.1d9",	"Apple II Setup 2.1d9"};